        existing = ''
        if os.path.exists(path):
            with open(path, 'r') as f:
                existing = f.read()
        new_entries = [(v, s) for v, s in _CHANGELOG if f"### {v}" not in existing]
        if not existing:
            header = "# OMEGA V60 — Changelog\n\n_Auto-generated by the bot. Newest versions appended at the bottom._\n\n"
            with open(path, 'w') as f:
                f.write(header)
                for v, s in _CHANGELOG:
                    f.write(f"### {v}\n{s}\n\n")
        elif new_entries:
            with open(path, 'a') as f:
                for v, s in new_entries:
                    f.write(f"### {v}\n{s}\n\n")

